import {coco,coin} from './art.mjs';
const styles=String.raw`
*{box-sizing:border-box} :root{font-family:ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#14243b;background:#f5f6fa;font-synthesis:none}body{margin:0}button,input,select{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.45}button:focus-visible,a:focus-visible{outline:3px solid #dda921;outline-offset:4px}input:focus,select:focus{outline:2px solid #b99545;outline-offset:2px}.shell{max-width:1500px;margin:auto;display:grid;grid-template-columns:222px 1fr;min-height:100vh}.sidebar{background:#112b47;color:#fff;display:flex;flex-direction:column;padding:30px 20px;position:sticky;top:0;height:100vh}.brand{display:flex;gap:10px;align-items:center;font-size:21px;font-weight:850;letter-spacing:-.7px}.brand img{width:40px}.brand small{display:block;font-size:10px;font-weight:600;letter-spacing:2px;color:#e6bd5c;margin-top:3px}.side-label{font-size:10px;letter-spacing:1.6px;color:#96abc0;margin:43px 12px 13px}.nav{display:grid;gap:7px}.nav button{border:0;background:transparent;color:#b5c5d6;text-align:left;padding:13px 15px;border-radius:12px;font-weight:650;font-size:14px}.nav button span{font-size:18px;display:inline-block;width:30px}.nav button.active{background:#25415c;color:#fff;box-shadow:inset 3px 0 #e8bd63}.side-bottom{margin-top:auto;font-size:12px;color:#9fb3c8;line-height:1.6;padding:20px 12px}.side-bottom b{color:#efc975}.exit{background:#ffffff10;border:1px solid #ffffff25;border-radius:10px;color:white;padding:11px;width:100%;margin-top:15px}.main{min-width:0;padding:24px 34px 40px}.topbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:25px}.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:10px;font-weight:800;color:#7b8799}.topbar h1{font-size:24px;letter-spacing:-.8px;margin:5px 0}.private{font-size:11px;font-weight:700;border:1px solid #e5d8b5;background:#fff9e9;color:#806226;border-radius:99px;padding:8px 12px}.avatar{width:35px;height:35px;border-radius:50%;display:grid;place-items:center;background:#e5eaf0;font-size:12px;font-weight:800}.row{display:flex;align-items:center;gap:12px}.hero{position:relative;overflow:hidden;min-height:245px;border-radius:22px;background:linear-gradient(115deg,#122c49,#254d6b);padding:29px 36px;color:white;margin-bottom:23px}.hero:after{content:'';position:absolute;border:1px solid #ffffff13;border-radius:50%;width:380px;height:380px;right:-70px;top:-60px;box-shadow:0 0 0 50px #ffffff03,0 0 0 105px #ffffff03}.hero-copy{position:relative;z-index:1;width:65%}.hero .eyebrow{color:#e6bc68}.hero h2{font-size:33px;line-height:1.12;letter-spacing:-1px;margin:14px 0 12px;max-width:510px}.hero p{font-size:13px;line-height:1.7;color:#d4e1ed;max-width:400px}.hero img.coco{position:absolute;right:25px;bottom:-26px;width:240px;z-index:1;filter:drop-shadow(0 8px 14px #061c3599)}.btn{background:#eabf65;border:0;border-radius:10px;padding:12px 17px;color:#172c45;font-weight:800;font-size:12px;display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:42px}.btn.dark{background:#173a57;color:white}.btn.light{background:#edf1f5;color:#24415b}.btn.outline{border:1px solid #d7dfe8;background:transparent}.btn.danger{background:#fbeae7;color:#a63831}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin:21px 0}.stat{background:white;border:1px solid #e8ecf1;border-radius:15px;padding:17px}.stat .label{font-size:11px;color:#718093;display:flex;align-items:center;gap:6px}.stat strong{display:block;font-size:24px;letter-spacing:-.8px;margin:10px 0 4px}.stat small{font-size:10px;color:#8792a0}.positive{color:#258263}.negative{color:#b54c47}.grid{display:grid;grid-template-columns:1.55fr 1fr;gap:20px}.panel{background:white;border:1px solid #e6ebf1;border-radius:17px;padding:22px;margin-bottom:20px}.panel h2,.section-title{font-size:16px;letter-spacing:-.3px;margin:0 0 16px}.panel h3{font-size:13px;margin:0 0 8px}.muted{font-size:12px;color:#748195;line-height:1.7}.tiny{font-size:10px;color:#748195;line-height:1.6}.spread{display:flex;justify-content:space-between;align-items:center;gap:10px}.pill{font-size:10px;border-radius:6px;background:#eff4f8;color:#526a82;padding:5px 8px;font-weight:700}.pill.gold{background:#fff5dc;color:#8a671d}.pill.green{background:#e8f4ee;color:#227251}.journey{display:flex;align-items:center;justify-content:space-between;margin:26px 0 20px;position:relative;gap:12px}.journey:before{content:'';position:absolute;top:23px;left:28px;right:28px;height:3px;background:#e7ebf0}.step{text-align:center;position:relative;font-size:10px;color:#7c8795;flex:1;z-index:1}.step i{font-style:normal;display:grid;place-items:center;border:6px solid white;border-radius:50%;width:49px;height:49px;background:#ecf0f4;margin:auto auto 9px;font-size:17px}.step.done i{background:#e5f2e8;color:#2f8265}.step.active i{background:#fce9b8;color:#866319}.progress{height:7px;border-radius:8px;background:#edf0f4;overflow:hidden;margin:12px 0}.progress b{display:block;height:100%;background:#d7a949;border-radius:8px}.quote{background:#f2f6f9;border-left:3px solid #d5ac55;border-radius:7px;padding:13px;font-size:12px;line-height:1.6;color:#51657b;margin-top:15px}.moneyline,.ledger-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid #edf0f4;font-size:12px}.moneyline:last-child,.ledger-row:last-child{border:0}.moneyline strong{white-space:nowrap}.moneyline .square{width:34px;height:34px;border-radius:9px;background:#f0f3f7;display:grid;place-items:center;font-size:16px}.market-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.asset{background:white;border:1px solid #e4e9ef;border-radius:17px;padding:20px;min-width:0}.asset-top{display:flex;gap:11px;align-items:center;margin-bottom:16px}.asset-logo{height:38px;width:38px;flex-shrink:0;border-radius:10px;display:grid;place-items:center;font-size:22px;font-weight:850}.asset h3{font-size:13px;line-height:1.4;margin:0}.asset p{font-size:11px;line-height:1.7;color:#708095}.asset .price{font-size:23px;font-weight:800;letter-spacing:-.7px;margin:7px 0}.risk{display:flex;gap:4px;align-items:center;margin:12px 0;font-size:10px;color:#7a8796}.risk i{height:5px;width:13px;border-radius:3px;background:#e7ebef}.risk i.on{background:#dba74c}.asset .btn{width:100%;margin-top:5px}.two{display:grid;grid-template-columns:1fr 1fr;gap:15px}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.field{display:flex;flex-direction:column;gap:7px;font-size:11px;color:#52667c;font-weight:650}.field input,.field select{width:100%;min-height:43px;border:1px solid #dce2e9;background:#fff;border-radius:9px;padding:10px 11px;color:#1c354e;font-size:13px}.field small{font-size:10px;font-weight:400;color:#7f8a99}.form-group-title{grid-column:1/-1;color:#183854;font-size:13px;margin:14px 0 0;border-top:1px solid #edf0f4;padding-top:19px}.wide{grid-column:1/-1}.form-footer{display:flex;gap:15px;justify-content:space-between;align-items:center;margin-top:22px}.notice{padding:13px 16px;border-radius:10px;background:#fff7e6;color:#816229;font-size:11px;line-height:1.6;margin:15px 0}.empty{padding:22px 5px;text-align:center;font-size:12px;color:#8090a2}.status{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);z-index:90;max-width:min(90vw,600px);padding:14px 22px;border-radius:12px;background:#173a57;color:white;font-size:13px;box-shadow:0 10px 40px #152b4433}.status.error{background:#973f3d}.status:empty{display:none}.modal-wrap{position:fixed;inset:0;background:#071e38a6;display:flex;align-items:center;justify-content:center;padding:20px;z-index:60;backdrop-filter:blur(5px)}.modal{background:#fff;border-radius:20px;max-width:520px;width:100%;padding:26px;max-height:90vh;overflow:auto}.modal h2{font-size:21px;margin:0 0 14px}.modal p{font-size:13px;line-height:1.8;color:#60748a}.modal .field{margin:14px 0}.modal .choice{display:block;border:1px solid #dfe6ed;border-radius:10px;background:#f8fafc;color:#27445e;text-align:left;padding:13px;width:100%;margin:10px 0;font-size:12px}.modal-head{display:flex;justify-content:space-between;align-items:center}.close{border:0;background:#eef2f5;border-radius:50%;height:30px;width:30px;font-size:18px;color:#5d7286}.loading{min-height:100vh;display:grid;place-items:center;background:#112b47;color:white}.loading span{letter-spacing:2px;font-size:14px}.source-note{font-size:10px;color:#8b96a5;line-height:1.7;margin-top:23px}.learning-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.lesson-card{padding:23px;border:1px solid #e3e9ef;background:#fff;border-radius:15px}.lesson-card h3{font-size:15px;margin:10px 0}.lesson-card p{font-size:12px;line-height:1.7;color:#6d7f92}.badge-icon{font-size:24px}.bill-action{display:flex;align-items:center;gap:12px}.coin-inline{width:27px;height:27px;vertical-align:middle}.spark{height:35px;display:flex;align-items:end;gap:3px;margin:13px 0}.spark b{background:#829eaa99;flex:1;border-radius:3px 3px 0 0;min-height:4px}.reward{background:#fff8e8;border:1px solid #f1e2c0}.section-head{display:flex;align-items:center;justify-content:space-between;margin:20px 0 14px}.section-head h2{margin:0}.footer{display:flex;justify-content:space-between;gap:12px;font-size:10px;color:#8b96a5;margin-top:30px;line-height:1.6}.mobile-back{display:none}.nowrap{white-space:nowrap}
@media(min-width:1350px){.hero img.coco{width:265px;right:55px}.hero{min-height:265px}}
@media(max-width:1100px){.shell{grid-template-columns:185px 1fr}.main{padding:22px}.sidebar{padding:26px 14px}.hero h2{font-size:29px}.hero img.coco{width:210px;right:5px}.hero{padding:25px}.market-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr 1fr}.brand{font-size:17px}}
@media(max-width:700px){.shell{display:block}.main{padding:18px 16px 100px}.sidebar{height:67px;padding:8px 5px;position:fixed;bottom:0;top:auto;left:0;right:0;z-index:50;padding-bottom:max(8px,env(safe-area-inset-bottom));box-sizing:content-box}.sidebar .brand,.side-label,.side-bottom{display:none}.nav{display:flex;justify-content:space-around;gap:0}.nav button{font-size:9px;padding:8px 2px;text-align:center;flex:1;border-radius:7px}.nav button span{display:block;margin:auto;width:auto;font-size:19px;margin-bottom:3px}.nav button.active{box-shadow:inset 0 -2px #e8bd63}.topbar{margin-bottom:16px}.topbar h1{font-size:21px}.topbar .avatar{display:none}.private{font-size:9px;padding:6px 9px}.mobile-back{display:inline-flex;border:0;background:#e8edf2;color:#27445e;border-radius:7px;font-size:10px;padding:7px;margin-bottom:15px}.hero{padding:23px 20px;min-height:250px;border-radius:17px}.hero h2{font-size:27px;max-width:230px}.hero-copy{width:72%}.hero p{font-size:11px;width:78%;line-height:1.7}.hero img.coco{width:158px;right:-26px;bottom:-14px}.hero .eyebrow{font-size:8px;letter-spacing:1.4px}.hero .btn{font-size:10px;padding:10px 12px}.stats{gap:9px;margin:17px 0}.stat{padding:14px}.stat strong{font-size:21px}.stat .label{font-size:10px}.stat small{font-size:9px}.panel{padding:18px;border-radius:14px}.market-grid{gap:10px}.asset{padding:14px;border-radius:13px}.asset-top{gap:7px;align-items:flex-start}.asset-logo{width:29px;height:29px;font-size:17px;border-radius:7px}.asset h3{font-size:11px}.asset .price{font-size:19px}.asset .tiny{font-size:9px}.asset .btn{font-size:10px;padding:9px}.risk{font-size:9px;gap:2px}.risk i{width:9px}.two,.learning-grid{grid-template-columns:1fr}.form-grid{gap:13px}.field{font-size:10px}.form-footer{align-items:flex-start;flex-direction:column}.form-footer .btn{width:100%}.footer{display:block}.modal{padding:22px}.journey{gap:3px}.step{font-size:9px}.section-head{align-items:flex-start}.bill-action{gap:7px}.moneyline{font-size:11px}}
`;
function app(){
 const channel=window.BANK_CHANNEL,root=document.getElementById('app');let data=null,tab='home',busy=false,modal=null;
 const pending=new Map();let seq=0;
 function api(path,body){return new Promise((resolve,reject)=>{const id=++seq;const timer=setTimeout(()=>{pending.delete(id);reject(new Error('La conexión está tardando. Vuelve a intentarlo.'))},25000);pending.set(id,{resolve,reject,timer});parent.postMessage({cocoBank:true,channel,id,path,body},'*')})}
 addEventListener('message',e=>{if(e.source!==parent||e.data?.channel!==channel||!e.data?.reply)return;const p=pending.get(e.data.id);if(p){clearTimeout(p.timer);pending.delete(e.data.id);e.data.error?p.reject(new Error(e.data.error)):p.resolve(e.data.data)}});
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const num=(n,d=2)=>Number(n||0).toLocaleString('es-ES',{maximumFractionDigits:d});
 const cb=n=>num(n/1000,3)+' CB';const eur=n=>num(n/100,2)+' €';
 const date=t=>new Date(t).toLocaleDateString('es-ES',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
 const today=()=>new Date(data?.serverTime||Date.now()).toISOString().slice(0,10);
 const now=()=>data?.serverTime||Date.now();
 function message(text,error=false){const el=document.getElementById('status');el.textContent=text;el.className='status'+(error?' error':'');clearTimeout(message.timer);message.timer=setTimeout(()=>el.textContent='',6500)}
 async function send(a){if(busy)return;busy=true;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);try{data=await api('/action',{...a,requestId:crypto.randomUUID()});modal=null;render();message('Guardado en tu banco virtual.')}catch(e){message(e.message,true)}finally{busy=false;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false)}}
 const navs=[['home','⌂','Mi banco'],['invest','↗','Invertir'],['life','▦','Mi vida'],['challenge','⚑','Mi desafío'],['learn','✧','Aprender']];
 const labels={house:'Casa',car:'Coche',other:'Administración'};
 function shell(body){return `<div class="shell"><aside class="sidebar"><div class="brand"><img src="${window.ART.coin}" alt="">COCO BANK<small></small></div><div class="side-label">TU PRÓXIMA GRAN IDEA</div><nav class="nav" aria-label="Banco">${navs.map(([id,icon,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav><div class="side-bottom"><b>Pequeñas decisiones.<br>Grandes aprendizajes.</b><p>1 Cocobit = 10 €<br>Todo el dinero es virtual.</p><button class="exit" data-close>← Volver a Coco</button></div></aside><main class="main"><button class="mobile-back" data-close>← Volver a Coco</button><header class="topbar"><div><div class="eyebrow">COCO EN FORMA / FINANZAS</div><h1>${navs.find(n=>n[0]===tab)?.[2]}</h1></div><div class="row"><span class="private">◈ Revisión privada · Diego</span><span class="avatar">DP</span></div></header>${body}<footer class="footer"><span>COCO BANK · Aprender haciendo, paso a paso.</span><span>Simulación educativa · Sin compras ni dinero real</span></footer></main></div><div class="status" id="status" role="status" aria-live="polite"></div><div id="modal"></div>`}
 function hero(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">TU FUTURO EMPIEZA CON UNA DECISIÓN</div><h2>Haz crecer tu dinero.<br>Y tu cabeza.</h2><p>Soy Coco. Vamos a aprender a invertir, cuidar nuestras responsabilidades y darle tiempo a las buenas decisiones.</p><button class="btn" ${data.state?'data-tab="invest"':'data-start'}>${data.state?'Explorar inversiones':'Crear mi primer desafío'} <span>→</span></button></div><img class="coco" src="${window.ART.coco}" alt="Coco, el pingüino de cerebro rosa, con chaleco azul y corbata dorada"></section>`}
 function stats(){const s=data.state,i=data.summary;return `<section class="stats" aria-label="Tu dinero"><div class="stat"><span class="label">◉ Saldo de tu cuenta</span><strong>${cb(s.cash)}</strong><small>${eur(s.cash)} virtuales</small></div><div class="stat"><span class="label">↗ Tu cartera</span><strong>${cb(i.value)}</strong><small>Aportado: ${cb(i.contributed)}</small></div><div class="stat"><span class="label">✦ Rendimiento de inversión</span><strong class="${i.returnPct>=0?'positive':'negative'}">${i.returnPct>=0?'+':''}${num(i.returnPct)} %</strong><small>El sueldo no cuenta como ganancia</small></div><div class="stat"><span class="label">▤ Libre para invertir</span><strong>${cb(i.available)}</strong><small>Gastos y reserva ya protegidos</small></div></section>`}
 function challengePanel(){const s=data.state,i=data.summary,c=s.config,progress=c.target>0?Math.max(0,Math.min(100,i.returnPct/c.target*100)):0,finished=now()>c.endsAt;const doneBills=!s.bills.some(b=>!b.paid);return `<section class="panel"><div class="spread"><h2>Tu camino hacia ${esc(c.title)}</h2><span class="pill gold">${finished?'Plazo terminado':i.daysLeft+' días'}</span></div><div class="journey"><div class="step done"><i>✓</i>Empieza</div><div class="step ${doneBills?'done':'active'}"><i>⌂</i>Organízate</div><div class="step ${s.contributed?'done':'active'}"><i>↗</i>Invierte</div><div class="step ${finished?'done':''}"><i>◷</i>Espera</div><div class="step ${i.returnPct>=c.target&&s.contributed?'done':''}"><i>⚑</i>Tu objetivo</div></div><div class="spread muted"><span>Rendimiento: ${num(i.returnPct)} %</span><strong>Meta: +${num(c.target)} %</strong></div><div class="progress"><b style="width:${progress}%"></b></div><div class="spread tiny"><span>${date(c.startsAt)} → ${date(c.endsAt)}</span><button class="btn light" data-tab="challenge">Ver desafío</button></div><div class="quote">${finished?'El plazo ha terminado. Revisa qué decisiones tomaste, el resultado y lo que aprendiste.':`La paciencia también juega. Tu meta es una referencia educativa, no una rentabilidad prometida.`}</div></section>`}
 function lifePanel(){const s=data.state,c=s.config;return `<section class="panel"><div class="spread"><h2>Primero, lo importante</h2><span class="pill">Cada mes</span></div><div class="moneyline"><span class="row"><span class="square">↓</span>Mi sueldo</span><strong class="positive">+${cb(c.salary)}</strong></div>${Object.entries(c.expenses).map(([k,v])=>`<div class="moneyline"><span class="row"><span class="square">${k==='house'?'⌂':k==='car'?'▰':'▤'}</span>${labels[k]}</span><strong>−${cb(v)}</strong></div>`).join('')}<div class="moneyline"><span>Reserva protegida</span><strong>${cb(c.reserve)}</strong></div><button class="btn light" style="width:100%;margin-top:15px" data-tab="life">Gestionar mis responsabilidades →</button></section>`}
 function ledger(limit=8){const s=data.state;return s.ledger.length?s.ledger.slice(0,limit).map(l=>`<div class="ledger-row"><span>${esc(l.text)}<br><small class="tiny">${date(l.at)}</small></span><strong class="${l.amount>0?'positive':''}">${l.amount?cb(l.amount):'—'}</strong></div>`).join(''):'<div class="empty">Tus decisiones aparecerán aquí.</div>'}
 function home(){if(!data.state)return hero()+`<section class="panel"><div class="eyebrow">BIENVENIDO A TU BANCO VIRTUAL</div><h2 style="margin-top:12px">Un objetivo. Un plan. Tus decisiones.</h2><div class="two"><p class="muted">Recibirás un sueldo, pagarás los gastos de tu casa y tu coche, guardarás una reserva y decidirás qué parte invertir. Tu familia elige el plazo y acuerda la recompensa.</p><div class="quote">Cada Cocobit representa 10 € virtuales. Las cotizaciones reflejan el mercado real, pero aquí puedes equivocarte y aprender sin arriesgar dinero.</div></div><button class="btn dark" data-start>Configurar desafío familiar →</button></section>`+`<div class="two"><section class="panel"><h2>↗ Aprende a invertir</h2><p class="muted">Acciones, plazos fijos, un fondo de bonos y Bitcoin. Descubre cómo funcionan antes de mover tu primera moneda.</p><button class="btn light" data-tab="learn">Conocer los instrumentos</button></section><section class="panel reward"><h2>◷ El tiempo forma parte del juego</h2><p class="muted">Sin carreras por duplicar el dinero. Plazos reales, una referencia razonable y decisiones que se valoran junto con el aprendizaje.</p><span class="pill gold">La familia elige la fecha de finalización</span></section></div>`;
 return hero()+stats()+`<div class="grid"><div>${challengePanel()}<section class="panel"><div class="spread"><h2>Últimos movimientos</h2><span class="pill">Tu historia</span></div>${ledger(5)}</section></div><div>${lifePanel()}<section class="panel reward"><h2>✧ La idea de Coco</h2><p class="muted">Invertir es aceptar incertidumbre. Repartir tu dinero entre distintas inversiones puede reducir el impacto de una caída, pero no elimina el riesgo.</p><button class="btn outline" data-tab="learn">Aprender algo nuevo</button></section></div></div>`}
 const fresh=p=>p&&now()-p.at<5*86400000&&now()-p.fetchedAt<36*3600000;
 function assetCard(c){const p=data.market.prices[c.id],h=data.state?.holdings[c.id];return `<article class="asset"><div class="asset-top"><span class="asset-logo" style="background:${c.color}">${c.icon}</span><div><h3>${esc(c.name)}</h3><span class="tiny">${c.kind}</span></div></div><div class="price">${p?num(p.eur)+' €':'Pendiente'}</div><div class="tiny">${p?'Por unidad · '+date(p.at):'Esperando datos de mercado'}</div><div class="risk">Riesgo ${Array.from({length:5},(_,i)=>`<i class="${i<c.risk?'on':''}"></i>`).join('')} ${['','','Moderado','Alto','Alto','Muy alto'][c.risk]}</div>${h?`<p>Tienes ${num(h.qty,6)} unidades<br><b>${cb(Math.round(h.qty*(p?.eur||h.lastEur)*100))}</b> en tu cartera</p>`:''}<button class="btn light" data-lesson="${c.id}">${data.state?.lessons.includes(c.id)?'✓ Ficha aprendida':'Leer la ficha de Coco'}</button><button class="btn dark" data-buy="${c.id}" ${!data.state||!fresh(p)?'disabled':''}>${fresh(p)?'Invertir Cocobits':'Cotización pendiente'}</button>${h?`<button class="btn outline" data-sell="${c.id}">Vender mi posición</button>`:''}</article>`}
 function invest(){const s=data.state,m=data.market;return `<div class="spread"><div><h2 class="section-title">Elige con la cabeza</h2><p class="muted">Comprende cada instrumento y su riesgo antes de invertir.</p></div><span class="pill">1 CB = 10 €</span></div>${s?stats():''}<div class="notice">Las órdenes se ejecutan con la siguiente cotización disponible posterior a tu decisión. Hay una actualización cada 24 horas; en días sin bolsa, se conserva el último cierre.</div><div class="market-grid"><article class="asset"><div class="asset-top"><span class="asset-logo" style="background:#f8eed4">◷</span><div><h3>Plazo fijo educativo</h3><span class="tiny">Referencia real: €STR del BCE</span></div></div><div class="price">${m.rate?num(m.rate.annualPct,3)+' %':'Pendiente'}</div><div class="tiny">Tasa anual · ${m.rate?date(m.rate.date):'Sin referencia'}</div><p>Bloqueas una cantidad durante 30, 90 o 180 días. Conoces el cálculo del interés al empezar.</p><button class="btn light" data-lesson="DEPOSIT">${s?.lessons.includes('DEPOSIT')?'✓ Ficha aprendida':'Leer la ficha de Coco'}</button><button class="btn dark" data-deposit ${!s||!m.rate?'disabled':''}>Abrir un plazo fijo</button><p class="tiny">Simulación con referencia €STR. No es una oferta de un banco real.</p></article>${data.catalog.map(assetCard).join('')}</div>${s?portfolio():''}${sourceNote()}`}
 function portfolio(){const s=data.state;return `<div class="two" style="margin-top:20px"><section class="panel"><h2>Órdenes pendientes</h2>${s.orders.length?s.orders.map(o=>`<div class="moneyline"><span>${o.side==='buy'?'Comprar':'Vender'} ${esc(o.asset)}<br><small class="tiny">${o.side==='buy'?cb(o.amount):num(o.qty,6)+' unidades'} · próximo precio</small></span><button class="btn light" data-cancel="${o.id}">Cancelar</button></div>`).join(''):'<p class="empty">Sin órdenes pendientes.</p>'}</section><section class="panel"><h2>Tus plazos y dividendos</h2>${s.deposits.map(d=>`<div class="moneyline"><span>Plazo fijo · ${num(d.rate,3)} % anual<br><small class="tiny">Vence el ${date(d.endsAt)}</small></span><strong>${cb(d.principal)}</strong></div>`).join('')||'<p class="muted">Todavía no tienes un plazo fijo.</p>'}<div class="moneyline"><span>Efectivo en cartera</span><strong>${cb(s.investmentCash)}</strong></div>${s.investmentCash?'<button class="btn light" data-withdraw>Traspasar a mi cuenta</button>':''}</section></div>`}
 function sourceNote(){const m=data.market;return `<p class="source-note">Última consulta: ${m.updatedAt?date(m.updatedAt)+' · '+new Date(m.updatedAt).toISOString().slice(11,16)+' UTC':'pendiente'}. Consulta diaria a las 12:00 UTC.<br>Acciones y fondo IEF: Yahoo Finance, cierre diario. Bitcoin: Coinbase, precio de referencia al consultar. Cambio de divisas y €STR: BCE. Las fracciones se simulan; sin comisiones ni impuestos. Dividendos modelados en la fecha ex-dividendo, con el cambio disponible. No se realizan operaciones financieras reales.</p>${m.errors?.length?`<div class="notice">Hay fuentes pendientes de actualizar. Se conserva su último dato con fecha y las operaciones se bloquean si deja de estar vigente.<details><summary>Ver estado de las fuentes</summary>${m.errors.map(esc).join('<br>')}</details></div>`:''}`}
 function life(){if(!data.state)return needsSetup();const s=data.state;return stats()+`<div class="grid"><section class="panel"><h2>Tus responsabilidades</h2><p class="muted">El sueldo y las facturas llegan cada mes, en el aniversario del inicio. Paga los gastos antes de planificar nuevas inversiones.</p>${s.bills.length?s.bills.slice().reverse().map(b=>`<div class="moneyline"><span>${labels[b.kind]}<br><small class="tiny">${date(b.at)}</small></span><div class="bill-action"><strong>${cb(b.amount)}</strong>${b.paid?'<span class="pill green">Pagado ✓</span>':`<button class="btn dark" data-pay="${b.id}">Pagar</button>`}</div></div>`).join(''):'<p class="empty">Las primeras facturas llegarán al comenzar el desafío.</p>'}</section><div>${lifePanel()}<section class="panel"><h2>Tu reserva es tranquilidad</h2><p class="muted">${cb(s.config.reserve)} quedan protegidos para imprevistos. Las facturas pendientes y las órdenes de compra también reducen el saldo que puedes invertir.</p></section></div></div><section class="panel"><h2>Todos tus movimientos</h2>${ledger(40)}</section>`}
 function needsSetup(){return `<section class="panel"><h2>Primero, pongamos una meta</h2><p class="muted">Tu familia elige el sueldo, los gastos, la reserva y las fechas.</p><button class="btn dark" data-start>Crear desafío</button></section>`}
 function challenge(){if(!data.state)return setup();const s=data.state,c=s.config,i=data.summary;return challengePanel()+`<div class="two"><section class="panel reward"><div class="eyebrow">ACUERDO FAMILIAR</div><h2 style="margin-top:13px">${esc(c.title)}</h2><p class="muted">Recompensa máxima acordada: <strong>${eur(c.reward)}</strong> reales.<br>La familia la entrega fuera del juego, después de revisar las decisiones y el aprendizaje. Los Cocobits no se canjean automáticamente.</p><div class="moneyline"><span>Inicio</span><strong>${date(c.startsAt)}</strong></div><div class="moneyline"><span>Final</span><strong>${date(c.endsAt)}</strong></div><div class="moneyline"><span>Objetivo de inversión</span><strong>+${num(c.target)} %</strong></div><p class="tiny">${c.referenceRate!==null?'Referencia anual al crear el desafío: '+num(c.referenceRate,3)+' % (€STR).':''} La rentabilidad futura no está garantizada.</p></section><section class="panel"><h2>Qué cuenta como ganancia</h2><div class="moneyline"><span>Aportado a inversiones</span><strong>${cb(i.contributed)}</strong></div><div class="moneyline"><span>Retirado de inversiones</span><strong>${cb(i.withdrawn)}</strong></div><div class="moneyline"><span>Valor actual de cartera</span><strong>${cb(i.value)}</strong></div><div class="moneyline"><span>Ganancia / pérdida acumulada</span><strong class="${i.profit>=0?'positive':'negative'}">${cb(i.profit)}</strong></div><p class="muted">El porcentaje sigue el valor de una participación virtual en tu cartera. Añadir dinero del sueldo o retirarlo no crea rentabilidad. Si no has invertido, el rendimiento es 0 %.</p></section></div><section class="panel"><h2>Panel de la familia · revisión privada</h2><p class="muted">Durante esta revisión solo Diego puede acceder. Puedes reiniciar la simulación para probar otras fechas y cantidades. Se eliminarán únicamente los datos de este desafío virtual.</p><button class="btn danger" data-reset>Reiniciar y configurar otro desafío</button></section>`}
 function setup(){let end=new Date(now());end.setUTCMonth(end.getUTCMonth()+3);return `<section class="panel"><div class="eyebrow">DISEÑA EL DESAFÍO EN FAMILIA</div><h2 style="margin-top:12px">Un plan que tiene sentido</h2><p class="muted">El plazo lo eliges tú. La referencia del mercado ayuda a fijar una meta realista; aprender y cuidar las responsabilidades también cuenta.</p><form id="setup"><div class="form-grid"><label class="field wide">¿Para qué estamos aprendiendo a ahorrar?<input name="title" value="Mi bicicleta" maxlength="80" required></label><label class="field">Fecha de inicio<input type="date" name="start" value="${today()}" min="${today()}" required></label><label class="field">Duración<select name="duration"><option value="1">1 mes</option><option value="3" selected>3 meses</option><option value="6">6 meses</option><option value="12">12 meses</option><option value="custom">Fechas a medida</option></select></label><label class="field">Fecha de finalización<input type="date" name="end" value="${end.toISOString().slice(0,10)}" required></label><div class="form-group-title">Tu economía virtual · 1 CB = 10 €</div><label class="field">Dinero inicial (CB)<input type="number" name="initial" value="10" min="0" max="1000000" step="0.001" required><small>10 CB = 100 € virtuales</small></label><label class="field">Sueldo mensual (CB)<input type="number" name="salary" value="150" min="0" max="1000000" step="0.001" required></label><label class="field">Reserva protegida (CB)<input type="number" name="reserve" value="20" min="0" max="1000000" step="0.001" required></label><label class="field">Casa cada mes (CB)<input type="number" name="house" value="60" min="0" max="1000000" step="0.001" required></label><label class="field">Coche cada mes (CB)<input type="number" name="car" value="20" min="0" max="1000000" step="0.001" required></label><label class="field">Administración cada mes (CB)<input type="number" name="other" value="15" min="0" max="1000000" step="0.001" required></label><div class="form-group-title">Una meta razonable, sin promesas</div><label class="field">Objetivo de rentabilidad<select name="targetMode"><option value="reference">Referencia del mercado</option><option value="custom">Elegir porcentaje</option></select></label><label class="field">Ganancia objetivo (%)<input type="number" name="target" min="0" max="100" step="0.01" required><small>Sobre la inversión, sin contar el sueldo</small></label><label class="field">Recompensa máxima familiar (€)<input type="number" name="rewardEuros" value="100" min="0" max="10000000" step="0.01" required></label><div class="notice wide" id="projection"></div></div><div class="form-footer"><p class="tiny">Solo dinero virtual. La familia decide y entrega cualquier recompensa real fuera de Coco Bank.</p><button type="submit" class="btn dark">Crear mi desafío →</button></div></form></section>`}
 function learn(){return `<h2 class="section-title">La academia de Coco</h2><p class="muted">Pequeñas explicaciones. Una pregunta. Una decisión más consciente.</p><div class="learning-grid">${[{id:'DEPOSIT',name:'¿Qué es un plazo fijo?',lesson:'Prestas tu dinero durante un tiempo y acuerdas cómo se calcula el interés. Si lo bloqueas, no puedes usarlo para pagar mañana.',icon:'◷'},...data.catalog].map(c=>`<article class="lesson-card"><span class="badge-icon">${c.icon}</span><h3>${esc(c.name)}</h3><p>${esc(c.lesson)}</p><button class="btn light" data-lesson="${c.id}">${data.state?.lessons.includes(c.id)?'✓ Aprendido · repasar':'Aprender con Coco →'}</button></article>`).join('')}</div><section class="panel" style="margin-top:20px"><h2>El dinero no crece por arte de magia</h2><p class="muted">El sueldo remunera tu trabajo. Las empresas obtienen ingresos vendiendo productos o servicios. Las inversiones pueden pagar intereses, dividendos o cambiar de precio: también pueden perder valor. El tiempo ayuda a planificar, pero esperar por sí solo no garantiza una ganancia.</p><div class="two"><div class="quote"><b>Interés compuesto.</b> Si una ganancia permanece invertida, puede generar nuevas ganancias. También seguirá expuesta al riesgo.</div><div class="quote"><b>Diversificación.</b> Repartir entre inversiones diferentes evita depender de una sola. No convierte una cartera en una garantía.</div></div></section>`}
 function render(){if(!data)return;root.innerHTML=shell(({home,invest,life,challenge,learn}[tab]||home)());if(tab==='challenge'&&!data.state)wireSetup();}
 function wireSetup(){const form=document.getElementById('setup');if(!form)return;function recalc(event){const f=form.elements;if(event?.target===f.start||event?.target===f.duration){if(f.duration.value!=='custom'){const d=new Date(f.start.value+'T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(f.duration.value));if(!isNaN(d))f.end.value=d.toISOString().slice(0,10)}}if(event?.target===f.end)f.duration.value='custom';const days=Math.max(0,(Date.parse(f.end.value)-Date.parse(f.start.value))/86400000),rate=data.market.rate?.annualPct,ref=rate===undefined?0:Math.max(0,rate)*days/365;f.target.readOnly=f.targetMode.value==='reference';if(f.target.readOnly)f.target.value=ref.toFixed(2);document.getElementById('projection').textContent=(rate===undefined?'La referencia del BCE todavía está pendiente. Puedes preparar el desafío con una meta de conservación del capital.':`Referencia anual del BCE: ${num(rate,3)} %. Para ${days} días equivale aproximadamente a ${num(ref)} %, sin capitalización. No es una promesa de rentabilidad.`)+' Saldo mensual después de gastos: '+num(Number(f.salary.value)-Number(f.house.value)-Number(f.car.value)-Number(f.other.value))+' CB.'}form.addEventListener('input',recalc);form.addEventListener('change',recalc);recalc();form.onsubmit=e=>{e.preventDefault();const c=Object.fromEntries(new FormData(form));c.reward=Number(c.rewardEuros)/10;send({type:'setup',config:c})}}
 function showModal(content){document.getElementById('modal').innerHTML=`<div class="modal-wrap"><section class="modal" role="dialog" aria-modal="true" aria-label="Coco Bank"><div class="modal-head"><span class="eyebrow">COCO TE ACOMPAÑA</span><button class="close" data-dismiss aria-label="Cerrar">×</button></div>${content}</section></div>`;document.querySelector('.modal button,.modal input')?.focus()}
 const lessons={DEPOSIT:{text:'En este plazo fijo educativo, el tipo anual se fija al abrir usando la referencia €STR del BCE. El dinero queda bloqueado hasta el vencimiento. Un 2 % anual no es un 2 % cada mes. La tasa se aplica a los días reales, sobre 365; los intereses se abonan al final. No representa una oferta ni una garantía bancaria real.',question:'Si bloqueas el dinero durante 90 días…',options:[['locked','Debo tener aparte el dinero de mis gastos.'],['free','Puedo gastarlo y seguir cobrando lo mismo.']]},AAPL:{question:'¿Una empresa que me gusta garantiza beneficios?',options:[['risk','No. Su acción también puede bajar.'],['sure','Sí, porque sus productos son buenos.']]},TSLA:{question:'¿La popularidad elimina el riesgo?',options:[['sure','Sí. Todas las empresas famosas suben.'],['risk','No. El precio puede caer mucho.']]},SAMSUNG:{question:'¿Qué puede cambiar mi resultado en euros?',options:[['currency','La acción y el cambio del won al euro.'],['price','Solo el precio de la acción.']]},BONDS:{question:'¿Qué puede hacer caer un fondo de bonos?',options:[['rates','Una subida de tipos y cambios de divisa.'],['safe','Nada. Todos los bonos están garantizados.']]},BTC:{question:'¿Qué conviene recordar con Bitcoin?',options:[['sure','Que siempre recuperará cualquier caída.'],['risk','Que puedo perder una parte importante.']]}};
 function lesson(id){const c=data.catalog.find(c=>c.id===id),l=lessons[id];showModal(`<h2 style="margin-top:18px">${esc(c?.name||'Plazo fijo educativo')}</h2><p>${esc(l.text||c.lesson)}</p><div class="quote">${l.question}</div>${l.options.map(([answer,text])=>`<button class="choice" data-answer="${id}:${answer}">${text}</button>`).join('')}${!data.state?'<p class="tiny">Puedes leer ahora. Crea un desafío para guardar tu aprendizaje.</p>':''}`)}
 function trade(id,deposit=false){if(!data.state)return;const c=data.catalog.find(c=>c.id===id);if(!data.state.lessons.includes(deposit?'DEPOSIT':id))return lesson(deposit?'DEPOSIT':id);showModal(`<h2 style="margin-top:18px">${deposit?'Abrir plazo fijo':esc(c.name)}</h2><p>Tienes <b>${cb(data.summary.available)}</b> libres para invertir. Los gastos pendientes y tu reserva están protegidos.</p><form id="trade"><label class="field">¿Cuántos Cocobits?<input type="number" name="amount" min="0.001" step="0.001" max="${data.summary.available/1000}" placeholder="Ej. 5" required></label>${deposit?'<label class="field">Plazo<select name="term"><option value="30">30 días</option><option value="90">90 días</option><option value="180">180 días</option></select></label><p class="tiny">Debe vencer antes del final del desafío. No podrás retirarlo antes.</p>':'<p class="tiny">La compra se ejecutará con el siguiente precio disponible. Su valor puede subir o bajar.</p>'}<button type="submit" class="btn dark" style="width:100%">${deposit?'Confirmar plazo virtual':'Dejar orden de compra'}</button></form>`);document.getElementById('trade').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);send({type:deposit?'deposit':'buy',asset:id,amount:f.get('amount'),term:f.get('term')})}}
 root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||busy)return;
 if(b.hasAttribute('data-close'))parent.postMessage({cocoBank:true,channel,close:true},'*');
 else if(b.dataset.tab){tab=b.dataset.tab;render();scrollTo(0,0)}
 else if(b.hasAttribute('data-start')){tab='challenge';render();scrollTo(0,0)}
 else if(b.hasAttribute('data-dismiss'))document.getElementById('modal').innerHTML='';
 else if(b.dataset.lesson)lesson(b.dataset.lesson);
 else if(b.dataset.answer){const [asset,answer]=b.dataset.answer.split(':');if(!data.state){if(lessons[asset].options.find(o=>o[0]===answer)&&['risk','currency','rates','locked'].includes(answer))message('¡Correcto! Crea un desafío para guardar tu progreso.');else message('Revisa la explicación e inténtalo otra vez.',true)}else send({type:'lesson',asset,answer})}
 else if(b.dataset.buy)trade(b.dataset.buy);
 else if(b.hasAttribute('data-deposit'))trade('DEPOSIT',true);
 else if(b.dataset.pay)send({type:'pay',billId:b.dataset.pay});
 else if(b.dataset.cancel)send({type:'cancel',orderId:b.dataset.cancel});
 else if(b.hasAttribute('data-withdraw'))send({type:'withdraw'});
 else if(b.dataset.sell){showModal(`<h2 style="margin-top:18px">Vender ${esc(b.dataset.sell)}</h2><p>Venderás toda tu posición al siguiente precio disponible. El resultado puede ser distinto al que ves ahora.</p><button class="btn dark" data-confirm-sell="${b.dataset.sell}">Dejar orden de venta</button>`)}
 else if(b.dataset.confirmSell)send({type:'sell',asset:b.dataset.confirmSell});
 else if(b.hasAttribute('data-reset'))showModal('<h2 style="margin-top:18px">¿Empezar otro desafío?</h2><p>Se borrarán la cartera, los movimientos y la configuración de esta simulación. Tu cuenta de Coco no se modifica.</p><button class="btn danger" data-confirm-reset>Reiniciar simulación</button>');
 else if(b.hasAttribute('data-confirm-reset'))send({type:'reset',confirm:'REINICIAR'});
 });
 addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('modal')?.replaceChildren()});
 async function load(){try{data=await api('/state');render()}catch(e){root.innerHTML='<div class="loading"><div><p>No se pudo abrir tu banco privado.</p><button class="btn" id="retry">Volver a intentar</button><p>'+esc(e.message)+'</p></div></div>';document.getElementById('retry').onclick=load}}load();
}
export function renderApp(){return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'unsafe-inline\'; style-src \'unsafe-inline\'; img-src data:; connect-src \'none\'; base-uri \'none\'; form-action \'none\'"><title>Coco Bank · revisión privada</title><style>'+styles+'</style></head><body><div id="app"><div class="loading"><span>COCO BANK · Abriendo tu banco…</span></div></div><script>window.BANK_CHANNEL="__BANK_CHANNEL__";window.ART='+JSON.stringify({coco,coin})+';('+app.toString()+')();</script></body></html>'}
